const b = $('Webhook').item.json.body;
const d = b.discussion;
const c = b.comment;
const body = c.body || '';
const agents = ($env.N8N_AGENT_LOGINS || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const mentions = (body.match(/@([a-zA-Z0-9-]+)/g) || []).map(m => m.slice(1));
const mentionedLogin = mentions.find(m => agents.includes(m.toLowerCase())) || '';
if (!d.node_id) {
  throw new Error('discussion.node_id missing');
}
// Threading: top-level mention → reply via replyToId; nested → fall back
// to a new top-level comment (parent's node_id isn't in the payload).
const isTopLevel = !c.parent_id;
const replyToNodeId = isTopLevel ? c.node_id : '';
const instruction = mentionedLogin ? body.replace(new RegExp('@' + mentionedLogin + '\\b', 'i'), '').trim() : body;
const args = {
  surface: 'discussion-comment',
  repoOwner: b.repository.owner.login,
  repoName: b.repository.name,
  repoFull: b.repository.full_name,
  senderLogin: b.sender && b.sender.login,
  senderType: b.sender && b.sender.type,
  discussionNumber: d.number,
  discussionTitle: d.title,
  discussionBody: d.body || '',
  discussionUrl: d.html_url,
  discussionNodeId: d.node_id,
  discussionCategory: (d.category && d.category.name) || '',
  commentId: c.id,
  commentBody: body,
  commentUrl: c.html_url,
  replyToNodeId,
  mentionedLogin,
  title: d.title,
  bodyText: body,
};
const threadingNote = replyToNodeId
  ? `Your reply will be posted as a threaded reply.`
  : `Your reply will be posted as a new top-level comment on the discussion (the original mention was a reply-to-a-reply, which GitHub doesn't support nesting further).`;
const prompt = `@${args.senderLogin} mentioned you in a comment on discussion #${args.discussionNumber} in category "${args.discussionCategory}".
Repo: ${args.repoFull}. URL: ${args.discussionUrl}.
${threadingNote}

Discussion title: ${args.discussionTitle}
Discussion body (for context):
---
${args.discussionBody}
---

Latest comment from @${args.senderLogin}:
---
${args.commentBody}
---

Instruction (mention stripped):
${instruction}

Reply in the discussion thread. Conversational only — no code changes. Markdown supported.

Return ONLY the reply body. No preamble.
`;
args.promptB64 = Buffer.from(prompt, 'utf8').toString('base64');
return [{ json: { argsB64: Buffer.from(JSON.stringify(args), 'utf8').toString('base64') } }];
